import Queue from 'better-queue';
import {v4 as uuidv4} from 'uuid';
import {ApplicationLog, ApplicationLogDao, Level} from './applog.esm.js';
import {Control} from '../internal-ts/control.esm.js';

export enum CommandTypes {
    SIMPLE = 'SIMPLE',
    SLEEP = 'SLEEP',
    FAILURE = 'FAILURE',
    EXCEPTION = 'EXCEPTION',
    MOVE = 'MOVE',
    MOVETO = 'MOVETO',
}

export interface CommandRequest {
    CommandType: string;
    Parameters: any;
}

export interface Command {
    // uuid generated by the client
    TaskId: string
    CommandType: string;
    Parameters: any;
    CreatedAt: string;
}

enum CommandStatus {
    PENDING = 'PENDING',
    RUNNING = 'RUNNING',
    FAILED = 'FAILED',
    COMPLETED = 'COMPLETED'
}

export interface CommandResult {
    TaskId: string;
    Command: Command;
    Result: any;
    Error: any;
    CompletedAt: string;
    Status?: CommandStatus;
}

export interface MoveToCoordinates {
    x: number;
    y: number;
}

export interface QueueMoveToRequest {
    Coordinates: MoveToCoordinates[];
    CronjobId?: string;
}

type ConsumerCallback = (input: Command) => Promise<CommandResult>;
type PushCallback = (error: Error | null, result: CommandResult) => void;

export interface CommandQueue {
    push(command: CommandRequest): string;

    getStatus(taskId: string): Promise<CommandResult | null>;

    lock(): void;

    unlock(): void;

    isLocked(): boolean;
}

export enum QeueuEventTypes {
    COMMAND_PROCESSED = 'COMMAND_PROCESSED',
    COMMAND_FAILED = 'COMMAND_FAILED',
    COMMAND_RUNNING = 'COMMAND_RUNNING',
}

function eventTypeToCommandStatus(eventType: string): CommandStatus {
    switch (eventType) {
        case QeueuEventTypes.COMMAND_PROCESSED:
            return CommandStatus.COMPLETED;
        case QeueuEventTypes.COMMAND_FAILED:
            return CommandStatus.FAILED;
        case QeueuEventTypes.COMMAND_RUNNING:
            return CommandStatus.RUNNING;
        default:
            return CommandStatus.PENDING;
    }
}

export class CommandQueueImpl implements CommandQueue {
    private queue: Queue;
    private applog: ApplicationLogDao;
    private locked: boolean;
    private motorControl: Control;

    constructor(appLog: ApplicationLogDao, motorControl: Control) {
        this.queue = new Queue(this.process.bind(this));
        this.queue.on('task_failed', this.failureHandler.bind(this));
        this.queue.on('task_accepted', this.taskAcceptedHandler.bind(this));
        this.applog = appLog;
        // when it's locked we can't push anything to the queue
        this.locked = false;
        this.motorControl = motorControl;
    }

    lock(): void {
        this.locked = true;
    }

    unlock(): void {
        this.locked = false;
    }

    isLocked(): boolean {
        return this.locked;
    }

    async getStatus(taskId: string): Promise<CommandResult | null> {
        const logs = await this.applog.getById(taskId);
        if (logs == null || logs.length == 0) {
            return null;
        }

        const latestLog = logs[logs.length - 1];
        const status = latestLog.EventType;

        let commandResult = logs[logs.length - 1].Payload as CommandResult;
        commandResult.Status = eventTypeToCommandStatus(status);
        return commandResult;
    }

    async failureHandler(taskID: string, error: Error, stats: any): Promise<void> {
        console.error(`Task ${taskID} failed with error ${error.message} with type : ${typeof error}`);

        let logEntry: ApplicationLog = {
            EventID: taskID,
            EventType: QeueuEventTypes.COMMAND_FAILED,
            Payload: {
                Command: {
                    TaskId: taskID,
                },
                Error: `${JSON.stringify(error.message)}`,
                CompletedAt: new Date().toISOString(),
            },
            CreatedAt: new Date().toISOString(),
            Level: Level.ERROR,
        };
        await this.applog.create(logEntry);
    }

    async taskAcceptedHandler(taskID: string, commandData: any): Promise<void> {
        const command = commandData as Command;
        let logEntry: ApplicationLog = {
            EventID: taskID,
            EventType: QeueuEventTypes.COMMAND_RUNNING,
            Payload: command,
            CreatedAt: new Date().toISOString(),
            Level: Level.INFO,
        };
        console.log(`Task ${taskID} accepted with data ${JSON.stringify(command)}`);
        await this.applog.create(logEntry);
    }

    async consumerCallback(command: Command): Promise<CommandResult> {
        let result: CommandResult = {
            TaskId: command.TaskId,
            Command: command,
            Result: "",
            Error: null,
            CompletedAt: new Date().toISOString()
        }

        let logEntry: ApplicationLog = {
            EventID: command.TaskId,
            EventType: QeueuEventTypes.COMMAND_PROCESSED,
            Payload: result,
            CreatedAt: new Date().toISOString(),
            Level: Level.INFO,
        };

        // here we're going to actuall call a command handler but it's fine
        // for now to just return a result
        if (command.CommandType == CommandTypes.SLEEP) {
            await new Promise(resolve => setTimeout(resolve, 1000));
            logEntry.EventType = QeueuEventTypes.COMMAND_PROCESSED;
        } else if (command.CommandType == CommandTypes.FAILURE) {
            result.Error = "Command failed";
            logEntry.EventType = QeueuEventTypes.COMMAND_FAILED;
            logEntry.Level = Level.ERROR;
        } else if (command.CommandType == CommandTypes.SIMPLE) {
            result.Result = "Command completed successfully";
            logEntry.EventType = QeueuEventTypes.COMMAND_PROCESSED;
        } else if (command.CommandType == CommandTypes.EXCEPTION) {
            throw new Error("Command failed with exception");
        } else if (command.CommandType == CommandTypes.MOVE) {
            const moveResult = await this.motorControl.move(command.Parameters);
            result.Result = moveResult;
            logEntry.EventType = QeueuEventTypes.COMMAND_PROCESSED;
        }else if(command.CommandType == CommandTypes.MOVETO){
            const params = command.Parameters as QueueMoveToRequest;
            const moveResults: string[] = [];
            for(let coord of params.Coordinates){
                const moveResult = await this.motorControl.moveTo(coord.x, coord.y);
                moveResults.push(`x: ${coord.x}, y: ${coord.y} - at ${new Date().toISOString()}`);
            }
            result.Result = moveResults;
            logEntry.EventType = QeueuEventTypes.COMMAND_PROCESSED;
        }
        else {
            result.Error = "Unknown command type";
            logEntry.EventType = QeueuEventTypes.COMMAND_FAILED;
            logEntry.Level = Level.ERROR;
        }

        try {
            await this.applog.create(logEntry);
        } catch (error) {
            console.error(error);
            throw error;
        }
        return result;
    }

    push(commandRequest: CommandRequest, pushCallback?: PushCallback): string {
        if (this.locked) {
            console.log("Queue is locked");
            throw new Error("Queue is locked");
        }

        const command: Command = {
            TaskId: uuidv4(),
            CommandType: commandRequest.CommandType,
            Parameters: commandRequest.Parameters,
            CreatedAt: new Date().toISOString()

        }

        const defaultCallback = (error: Error | null, result?: CommandResult) => {
            if (error) {
                console.log("[defaultCallback]Error processing command")
                console.error(error);
            } else {
                console.log(result);
            }
        }

        this.queue.push({...command, 'id': command.TaskId}, pushCallback || defaultCallback);
        return command.TaskId;
    }

    private async process(command: Command, cb: (error: Error | null, result?: CommandResult) => void): Promise<void> {
        try {
            const result: CommandResult = await this.consumerCallback(command);
            if (!result.CompletedAt) {
                result.CompletedAt = new Date().toISOString();
            }
            cb(null, result);
        } catch (error) {
            console.log(`Error processing command ${command.TaskId} -> ${JSON.stringify(error)}`);
            cb(error instanceof Error ? error : new Error(JSON.stringify(error)));
        }
    }
}


